1	import crypto from 'node:crypto';
2	/**
3	 * QuickBooks Routes — OAuth connection flow + invoice/payment sync.
4	 *
5	 * OAuth flow:
6	 *   1. GET /quickbooks/auth-url   → Build authorization URL
7	 *   2. POST /quickbooks/callback  → Exchange code for tokens, store encrypted
8	 *   3. GET /quickbooks/status     → Connection status
9	 *   4. POST /quickbooks/disconnect → Remove integration
10	 *
11	 * Sync endpoints (super-admin only):
12	 *   5. POST /quickbooks/sync/invoice/:invoiceId → Sync one invoice to QB
13	 *   6. POST /quickbooks/sync/payment/:invoiceId → Sync payment for invoice
14	 *   7. POST /quickbooks/sync/bulk               → Bulk-sync recent invoices
15	 *   8. GET  /quickbooks/sync/status             → Sync dashboard data
16	 */
