48	const INTUIT_AUTH_URL =
49	  'https://appcenter.intuit.com/app/connect/oauth2/authorize';
50	const INTUIT_TOKEN_URL =
51	  'https://oauth.platform.intuit.com/oauth2/v1/tokens/bearer';
52	const QB_SCOPES = 'com.intuit.quickbooks.accounting';
53	const LEGACY_QB_REPLACEMENT =
54	  'Use owner-scoped accounting_provider_connections via /api/integrations/qbo/* or /api/accounting/*';
