56	// ─── Encryption helpers ───────────────────────────────────────────────────
57	
58	function getEncryptionKey(): Buffer {
59	  const key = process.env.QUICKBOOKS_ENCRYPTION_KEY;
60	  if (!key) throw new Error('Missing QUICKBOOKS_ENCRYPTION_KEY');
61	  // Ensure 32-byte key for AES-256
62	  return crypto.createHash('sha256').update(key).digest();
63	}
64	
65	function encrypt(text: string): string {
66	  const key = getEncryptionKey();
67	  const iv = crypto.randomBytes(12);
68	  const cipher = crypto.createCipheriv('aes-256-gcm', key, iv);
69	  const encrypted = Buffer.concat([
70	    cipher.update(text, 'utf8'),
71	    cipher.final(),
72	  ]);
73	  const tag = cipher.getAuthTag();
74	  // Format: iv:tag:ciphertext (all base64)
75	  return `${iv.toString('base64')}:${tag.toString('base64')}:${encrypted.toString('base64')}`;
76	}
77	
78	function decrypt(encoded: string): string {
79	  const key = getEncryptionKey();
80	  const [ivB64, tagB64, dataB64] = encoded.split(':');
81	  const iv = Buffer.from(ivB64, 'base64');
82	  const tag = Buffer.from(tagB64, 'base64');
83	  const data = Buffer.from(dataB64, 'base64');
84	  const decipher = crypto.createDecipheriv('aes-256-gcm', key, iv);
85	  decipher.setAuthTag(tag);
86	  return decipher.update(data) + decipher.final('utf8');
87	}
