91	type DbExecuteResult<T> = T[] | { rows?: T[] };
92	
93	function rowsFrom<T>(result: DbExecuteResult<T>): T[] {
94	  return Array.isArray(result) ? result : (result.rows ?? []);
95	}
96	
97	function intValue(value: unknown): number {
98	  if (typeof value === 'number') return value;
99	  if (typeof value === 'bigint') return Number(value);
100	  if (typeof value === 'string') return Number.parseInt(value, 10) || 0;
101	  return 0;
102	}
103	
104	function isoValue(value: unknown): string | null {
105	  if (!value) return null;
106	  if (value instanceof Date) return value.toISOString();
107	  return String(value);
108	}
109	
110	async function singleMetric<T extends Record<string, unknown>>(
111	  query: ReturnType<typeof sql>,
112	): Promise<T> {
113	  const rows = rowsFrom<T>((await db.execute(query)) as DbExecuteResult<T>);
114	  return (rows[0] ?? {}) as T;
115	}
