118	  return (
119	    process.env.ENABLE_LEGACY_USER_SCOPED_QB_SYNC === 'true' ||
120	    (process.env.NODE_ENV === 'test' &&
121	      process.env.ENABLE_LEGACY_USER_SCOPED_QB_SYNC !== 'false')
