135	// ─── Wave 1 Practice-Mode Guard Helper ───────────────────────────────────────
136	/**
137	 * Checks whether a QB sync for the given invoiceId should be suppressed
138	 * because the school is in practice/onboarding mode.
139	 *
140	 * Returns false (allow through) when:
141	 *   - invoiceId not found
142	 *   - school has no onboarding_locations row (non-Wave-1 school — must NOT fail-closed)
143	 * Returns true (suppress) when onboarding_locations row exists AND onboardingMode = true.
144	 */
145	async function qbPracticeModeCheck(invoiceId: string): Promise<boolean> {
146	  const [inv] = await db
147	    .select({ flightSchoolId: invoices.flightSchoolId })
148	    .from(invoices)
149	    .where(eq(invoices.id, invoiceId))
150	    .limit(1);
151	  if (!inv?.flightSchoolId) return false;
152	
153	  const [obloc] = await db
154	    .select({ locationId: onboardingLocationsV2.locationId })
155	    .from(onboardingLocationsV2)
156	    .where(eq(onboardingLocationsV2.flightSchoolId, inv.flightSchoolId))
157	    .limit(1);
158	  if (!obloc) return false; // non-Wave-1 school — allow through
159	
160	  const guard = await practiceModeGuard({
161	    effectKind: 'quickbooks_commit',
162	    flightSchoolId: inv.flightSchoolId,
163	    locationId: obloc.locationId,
164	    payloadSummary: { invoiceId },
165	  });
166	  return !guard.allowed;
167	}
