169	/**
170	 * GET /quickbooks/auth-url — Build the Intuit OAuth2 authorization URL.
171	 */
172	quickbooks.get('/quickbooks/auth-url', requireAdmin(), async (c) => {
173	  if (!legacyUserScopedQuickBooksEnabled()) {
174	    return legacyUserScopedQuickBooksBlocked(c);
175	  }
176	  const clientId = process.env.QB_CLIENT_ID;
177	  if (!clientId) {
178	    return c.json({ error: 'QuickBooks integration not configured' }, 500);
179	  }
180	
181	  const redirectUri = resolveQBOOAuthRedirectUri();
182	
183	  const user = c.get('authUser') as AuthUser;
184	  const flightSchoolId = await resolveOrgIdFromSession(user, c);
185	  if (!flightSchoolId) {
186	    return c.json(
187	      { error: 'Could not resolve organization for this user' },
188	      403,
189	    );
190	  }
191	
192	  const state = await encryptState({
193	    flightSchoolId,
194	    nonce: crypto.randomUUID(),
195	    returnPath: '/school-admin/settings/integrations',
196	  });
197	
198	  const params = new URLSearchParams({
199	    client_id: clientId,
200	    response_type: 'code',
201	    scope: QB_SCOPES,
202	    redirect_uri: redirectUri,
203	    state,
204	  });
205	
206	  return c.json({ url: `${INTUIT_AUTH_URL}?${params.toString()}` });
207	});
208	
209	/**
210	 * POST /quickbooks/callback — Exchange the authorization code for tokens.
211	 */
212	quickbooks.post('/quickbooks/callback', requireAdmin(), async (c) => {
213	  if (!legacyUserScopedQuickBooksEnabled()) {
214	    return legacyUserScopedQuickBooksBlocked(c);
215	  }
216	  try {
217	    const { code, realmId, userId } = await c.req.json();
218	
219	    if (!code || !realmId) {
220	      return c.json({ error: 'Missing code or realmId' }, 400);
221	    }
222	
223	    const clientId = process.env.QB_CLIENT_ID;
224	    const clientSecret = process.env.QB_CLIENT_SECRET;
225	    if (!clientId || !clientSecret) {
226	      return c.json({ error: 'QuickBooks not configured' }, 500);
227	    }
228	
229	    const user = c.get('authUser') as AuthUser;
230	    const targetUserId = userId || user.id;
231	    let flightSchoolId: string | null = null;
232	    try {
233	      flightSchoolId = await resolveOrgIdFromSession(user, c);
234	    } catch {
235	      return c.json({ error: 'Could not resolve organization' }, 403);
236	    }
237	    if (!flightSchoolId) {
238	      return c.json({ error: 'Could not resolve organization' }, 403);
239	    }
240	
241	    const redirectUri = resolveQBOOAuthRedirectUri();
242	
243	    // Exchange code for tokens
244	    const basicAuth = Buffer.from(`${clientId}:${clientSecret}`).toString(
245	      'base64',
246	    );
247	
248	    const tokenRes = await fetch(INTUIT_TOKEN_URL, {
249	      method: 'POST',
250	      headers: {
251	        'Content-Type': 'application/x-www-form-urlencoded',
252	        Authorization: `Basic ${basicAuth}`,
253	        Accept: 'application/json',
254	      },
255	      body: new URLSearchParams({
256	        grant_type: 'authorization_code',
257	        code,
258	        redirect_uri: redirectUri,
259	      }),
260	    });
261	
262	    if (!tokenRes.ok) {
263	      const tokenError = await tokenRes
264	        .json()
265	        .then((body: unknown) => {
266	          if (!body || typeof body !== 'object') return {};
267	          const record = body as Record<string, unknown>;
268	          return {
269	            error: typeof record.error === 'string' ? record.error : undefined,
270	            errorDescription:
271	              typeof record.error_description === 'string'
272	                ? record.error_description
273	                : undefined,
274	          };
275	        })
276	        .catch(() => ({}));
277	      console.error('[QuickBooks] Token exchange failed', {
278	        status: tokenRes.status,
279	        ...tokenError,
280	      });
281	      return c.json({ error: 'Failed to exchange authorization code' }, 500);
282	    }
283	
284	    const tokens = (await tokenRes.json()) as {
285	      access_token: string;
286	      refresh_token: string;
287	      expires_in: number;
288	      x_refresh_token_expires_in?: number;
289	    };
290	
291	    const tokenData = {
292	      realmId,
293	      flightSchoolId,
294	      accessToken: encrypt(tokens.access_token),
295	      refreshToken: encrypt(tokens.refresh_token),
296	      expiresAt: new Date(Date.now() + tokens.expires_in * 1000).toISOString(),
297	      refreshExpiresAt: new Date(
298	        Date.now() +
299	          (typeof tokens.x_refresh_token_expires_in === 'number' &&
300	          Number.isFinite(tokens.x_refresh_token_expires_in) &&
301	          tokens.x_refresh_token_expires_in > 0
302	            ? tokens.x_refresh_token_expires_in
303	            : 95 * 24 * 60 * 60) *
304	            1000,
305	      ).toISOString(),
306	      connectedAt: new Date().toISOString(),
307	    };
308	
309	    // Upsert integration
310	    const [existing] = await db
311	      .select()
312	      .from(userIntegrations)
313	      .where(
314	        and(
315	          eq(userIntegrations.userId, targetUserId),
316	          eq(userIntegrations.integrationType, 'quickbooks'),
317	        ),
318	      )
319	      .limit(1);
320	
321	    if (existing) {
322	      await db
323	        .update(userIntegrations)
324	        .set({ tokenData, updatedAt: new Date() })
325	        .where(eq(userIntegrations.id, existing.id));
326	    } else {
327	      await db.insert(userIntegrations).values({
328	        userId: targetUserId,
329	        integrationType: 'quickbooks',
330	        tokenData,
331	      });
332	    }
333	
334	    return c.json({ success: true, realmId });
335	  } catch (err: unknown) {
336	    console.error('[QuickBooks] Callback error:', err);
337	    const msg = extractError(err);
338	    return c.json({ error: msg }, 500);
339	  }
340	});
