342	/**
343	 * GET /quickbooks/status — Return connection status.
344	 */
345	quickbooks.get('/quickbooks/status', requireAdmin(), async (c) => {
346	  if (!legacyUserScopedQuickBooksEnabled()) {
347	    return c.json({
348	      connected: false,
349	      disabled: true,
350	      replacement: LEGACY_QB_REPLACEMENT,
351	    });
352	  }
353	  try {
354	    const user = c.get('authUser') as AuthUser;
355	
356	    const [row] = await db
357	      .select()
358	      .from(userIntegrations)
359	      .where(
360	        and(
361	          eq(userIntegrations.userId, user.id),
362	          eq(userIntegrations.integrationType, 'quickbooks'),
363	        ),
364	      )
365	      .limit(1);
366	
367	    if (!row?.tokenData) {
368	      return c.json({ connected: false });
369	    }
370	
371	    const data = row.tokenData as Record<string, unknown>;
372	
373	    // If the refresh token has expired the connection is functionally dead.
374	    // Report disconnected so the badge doesn't falsely show Connected.
375	    const refreshExpiresAt = data.refreshExpiresAt as string | undefined;
376	    if (refreshExpiresAt && new Date(refreshExpiresAt) < new Date()) {
377	      return c.json({ connected: false });
378	    }
379	
380	    return c.json({
381	      connected: true,
382	      realmId: data.realmId,
383	      connectedAt: data.connectedAt,
384	    });
385	  } catch (err: unknown) {
386	    console.error('[QuickBooks] Status error:', err);
387	    return c.json({ error: 'Failed to check QuickBooks status' }, 500);
388	  }
389	});
