391	/**
392	 * POST /quickbooks/disconnect — Remove the QuickBooks integration.
393	 */
394	quickbooks.post('/quickbooks/disconnect', requireAdmin(), async (c) => {
395	  if (!legacyUserScopedQuickBooksEnabled()) {
396	    return legacyUserScopedQuickBooksBlocked(c);
397	  }
398	  try {
399	    const user = c.get('authUser') as AuthUser;
400	
401	    await db
402	      .delete(userIntegrations)
403	      .where(
404	        and(
405	          eq(userIntegrations.userId, user.id),
406	          eq(userIntegrations.integrationType, 'quickbooks'),
407	        ),
408	      );
409	
410	    return c.json({ success: true });
411	  } catch (err: unknown) {
412	    console.error('[QuickBooks] Disconnect error:', err);
413	    return c.json({ error: 'Failed to disconnect QuickBooks' }, 500);
414	  }
415	});
416	
417	quickbooks.get('/quickbooks/requires-reconnect', requireAdmin(), async (c) => {
418	  try {
419	    const user = c.get('authUser') as AuthUser;
420	    const flightSchoolId = await resolveOrgIdFromSession(user, c);
421	    if (!flightSchoolId) {
422	      return c.json(
423	        { error: 'Could not resolve organization for this user' },
424	        403,
425	      );
426	    }
427	
428	    const connection = await qbConnectionRepo.findBySchool(flightSchoolId);
429	    if (!connection) {
430	      return c.json({ required: false, reason: null });
431	    }
432	
433	    const daysRemaining = Math.floor(
434	      (connection.refreshTokenExpiresAt.getTime() - Date.now()) / 86_400_000,
435	    );
436	    if (daysRemaining < 0 || connection.status === 'token_expired') {
437	      return c.json({
438	        required: true,
439	        reason: 'expired',
440	        daysRemaining,
441	      });
442	    }
443	    if (daysRemaining < 20 || connection.status === 'refresh_expiring_soon') {
444	      return c.json({
445	        required: true,
446	        reason: 'expiring_soon',
447	        daysRemaining,
448	      });
449	    }
450	
451	    return c.json({ required: false, reason: null, daysRemaining });
452	  } catch (err: unknown) {
453	    console.error('[QuickBooks] Reconnect status error:', err);
454	    return c.json({ error: extractError(err) }, 500);
455	  }
456	});
