458	quickbooks.get('/quickbooks/sync-log', requireAdmin(), async (c) => {
459	  try {
460	    const user = c.get('authUser') as AuthUser;
461	    const flightSchoolId = await resolveOrgIdFromSession(user, c);
462	    if (!flightSchoolId) {
463	      return c.json(
464	        { error: 'Could not resolve organization for this user' },
465	        403,
466	      );
467	    }
468	
469	    const requestedLimit = Number(c.req.query('limit') ?? 50);
470	    const limit = Math.min(
471	      Math.max(Number.isFinite(requestedLimit) ? requestedLimit : 50, 1),
472	      50,
473	    );
474	    const entries = await qbSyncLogRepo.findBySchool(flightSchoolId, { limit });
475	    return c.json(entries);
476	  } catch (err: unknown) {
477	    console.error('[QuickBooks] Sync log error:', err);
478	    return c.json({ error: extractError(err) }, 500);
479	  }
480	});
