482	// ═══════════════════════════════════════════════════════════════════════════
483	// OPERATIONAL DIAGNOSTICS (super-admin only)
484	// ═══════════════════════════════════════════════════════════════════════════
485	
486	quickbooks.get('/quickbooks/diagnostics', requireSuperAdmin(), async (c) => {
487	  try {
488	    const flightSchoolId = c.req.query('flightSchoolId') ?? null;
489	    const scope = flightSchoolId
490	      ? sql`${flightSchoolId}::uuid`
491	      : sql`NULL::uuid`;
492	
493	    const [
494	      stripeSync,
495	      qbSync,
496	      failedSyncs,
497	      unresolvedConflicts,
498	      duplicateSuppressions,
499	      balanceMismatches,
500	      unmatchedStripe,
501	      unmatchedQb,
502	      orphanedPayments,
503	      externallyPaidUnpaidInternal,
504	      failedRowsResult,
505	    ] = await Promise.all([
506	      singleMetric<{ last_sync_at: unknown }>(sql`
507	        SELECT max(created_at) AS last_sync_at
508	        FROM stripe_sync_audit
509	        WHERE (${scope} IS NULL OR flight_school_id = ${scope})
510	      `),
511	      singleMetric<{ last_sync_at: unknown }>(sql`
512	        SELECT max(created_at) AS last_sync_at
513	        FROM qb_sync_log
514	        WHERE status = 'success'
515	          AND (${scope} IS NULL OR flight_school_id = ${scope})
516	      `),
517	      singleMetric<{ count: unknown }>(sql`
518	        SELECT count(*) AS count
519	        FROM qb_sync_log
520	        WHERE status = 'failed'
521	          AND created_at >= now() - interval '30 days'
522	          AND (${scope} IS NULL OR flight_school_id = ${scope})
523	      `),
524	      singleMetric<{ count: unknown }>(sql`
525	        SELECT count(*) AS count
526	        FROM stripe_reconciliation
527	        WHERE status = 'pending'
528	          AND (${scope} IS NULL OR flight_school_id = ${scope})
529	      `),
530	      singleMetric<{ count: unknown }>(sql`
531	        SELECT
532	          (
533	            SELECT count(*)
534	            FROM qb_sync_log
535	            WHERE status = 'skipped'
536	              AND (qb_error_code = 'DUP_SUP' OR qb_error_message ILIKE '%duplicate suppression%')
537	              AND (${scope} IS NULL OR flight_school_id = ${scope})
538	          )
539	          +
540	          (
541	            SELECT count(*)
542	            FROM stripe_sync_audit
543	            WHERE reason = 'DUPLICATE_CANDIDATES'
544	              AND (${scope} IS NULL OR flight_school_id = ${scope})
545	          ) AS count
546	      `),
547	      singleMetric<{ count: unknown }>(sql`
548	        SELECT count(*) AS count
549	        FROM (
550	          SELECT si.id
551	          FROM student_invoices si
552	          JOIN payment_transactions pt
553	            ON pt.invoice_id = si.id
554	           AND pt.status = 'completed'
555	           AND pt.type = 'sale'
556	          WHERE (${scope} IS NULL OR si.flight_school_id = ${scope})
557	          GROUP BY si.id, si.amount
558	          HAVING abs(coalesce(sum(pt.amount), 0) - si.amount) > 0
559	        ) mismatches
560	      `),
561	      singleMetric<{ count: unknown }>(sql`
562	        SELECT count(*) AS count
563	        FROM stripe_reconciliation
564	        WHERE status = 'pending'
565	          AND (${scope} IS NULL OR flight_school_id = ${scope})
566	      `),
567	      singleMetric<{ count: unknown }>(sql`
568	        SELECT count(*) AS count
569	        FROM qb_webhook_events qwe
570	        JOIN qb_connections qc ON qc.realm_id = qwe.realm_id
571	        LEFT JOIN qb_entity_map qem
572	          ON qem.flight_school_id = qc.flight_school_id
573	         AND qem.qb_entity_id = qwe.entity_id
574	         AND lower(qem.atos_entity_type) = lower(coalesce(qwe.entity_type, ''))
575	        WHERE qwe.entity_id IS NOT NULL
576	          AND qem.id IS NULL
577	          AND (${scope} IS NULL OR qc.flight_school_id = ${scope})
578	      `),
579	      singleMetric<{ count: unknown }>(sql`
580	        SELECT count(*) AS count
581	        FROM payment_transactions
582	        WHERE status = 'completed'
583	          AND invoice_id IS NULL
584	          AND (${scope} IS NULL OR flight_school_id = ${scope})
585	      `),
586	      singleMetric<{ count: unknown }>(sql`
587	        SELECT count(*) AS count
588	        FROM payment_transactions pt
589	        JOIN student_invoices si ON si.id = pt.invoice_id
590	        WHERE pt.status = 'completed'
591	          AND pt.type = 'sale'
592	          AND si.status <> 'paid'
593	          AND (${scope} IS NULL OR pt.flight_school_id = ${scope})
594	      `),
595	      db.execute(sql`
596	        SELECT id, flight_school_id, operation, entity_type, atos_entity_id,
597	               status, qb_error_code, qb_error_message, created_at
598	        FROM qb_sync_log
599	        WHERE status = 'failed'
600	          AND (${scope} IS NULL OR flight_school_id = ${scope})
601	        ORDER BY created_at DESC
602	        LIMIT 10
603	      `) as Promise<
604	        DbExecuteResult<{
605	          id: string;
606	          flight_school_id: string;
607	          operation: string;
608	          entity_type: string;
609	          atos_entity_id: string | null;
610	          status: string;
611	          qb_error_code: string | null;
612	          qb_error_message: string | null;
613	          created_at: unknown;
614	        }>
615	      >,
616	    ]);
617	
618	    const failedRows = rowsFrom(await failedRowsResult).map((row) => ({
619	      id: row.id,
620	      flightSchoolId: row.flight_school_id,
621	      operation: row.operation,
622	      entityType: row.entity_type,
623	      atosEntityId: row.atos_entity_id,
