1	import crypto from 'node:crypto';
2	/**
3	 * QuickBooks Online API Client
4	 *
5	 * Provides authenticated access to the QuickBooks Online REST API.
6	 * Reads encrypted OAuth tokens from the `userIntegrations` table,
7	 * handles automatic token refresh, and exposes typed methods for
8	 * common accounting operations (customers, invoices, payments).
9	 *
10	 * Uses native `fetch` — no external QB SDK required.
11	 */
12	import { db } from '@/lib/db';
13	import { userIntegrations } from '@/lib/schema';
14	import { and, eq } from 'drizzle-orm';
15	
16	// ─── Constants ───────────────────────────────────────────────────────────
17	
18	const INTUIT_TOKEN_URL =
19	  'https://oauth.platform.intuit.com/oauth2/v1/tokens/bearer';
20	
21	const QB_API_BASE =
22	  process.env.NODE_ENV === 'production'
23	    ? 'https://quickbooks.api.intuit.com'
24	    : 'https://sandbox-quickbooks.api.intuit.com';
25	
26	// ─── Encryption helpers (mirror routes-quickbooks.ts) ────────────────────
27	
28	function getEncryptionKey(): Buffer {
29	  const key = process.env.QUICKBOOKS_ENCRYPTION_KEY;
30	  if (!key) throw new Error('Missing QUICKBOOKS_ENCRYPTION_KEY');
31	  return crypto.createHash('sha256').update(key).digest();
32	}
33	
34	function encrypt(text: string): string {
35	  const key = getEncryptionKey();
36	  const iv = crypto.randomBytes(12);
37	  const cipher = crypto.createCipheriv('aes-256-gcm', key, iv);
38	  const encrypted = Buffer.concat([
39	    cipher.update(text, 'utf8'),
40	    cipher.final(),
41	  ]);
42	  const tag = cipher.getAuthTag();
43	  return `${iv.toString('base64')}:${tag.toString('base64')}:${encrypted.toString('base64')}`;
44	}
45	
46	function decrypt(encoded: string): string {
47	  const key = getEncryptionKey();
48	  const [ivB64, tagB64, dataB64] = encoded.split(':');
49	  const iv = Buffer.from(ivB64, 'base64');
50	  const tag = Buffer.from(tagB64, 'base64');
51	  const data = Buffer.from(dataB64, 'base64');
52	  const decipher = crypto.createDecipheriv('aes-256-gcm', key, iv);
53	  decipher.setAuthTag(tag);
54	  return decipher.update(data) + decipher.final('utf8');
55	}
