114	
115	/**
116	 * QuickBooks Online API client.
117	 *
118	 * Instantiate via `QuickBooksClient.create(userId)` — this reads the
119	 * encrypted tokens from the DB for the given user. All API methods
120	 * handle 401 responses by attempting a single token refresh + retry.
121	 */
122	export class QuickBooksClient {
123	  private accessToken: string;
124	  private refreshToken: string;
125	  private expiresAt: Date;
126	  private realmId: string;
127	  private userId: string;
128	  private integrationId: string;
129	
130	  private constructor(
131	    accessToken: string,
132	    refreshToken: string,
133	    expiresAt: Date,
134	    realmId: string,
135	    userId: string,
136	    integrationId: string,
137	  ) {
138	    this.accessToken = accessToken;
139	    this.refreshToken = refreshToken;
140	    this.expiresAt = expiresAt;
141	    this.realmId = realmId;
142	    this.userId = userId;
143	    this.integrationId = integrationId;
144	  }
145	
146	  /**
147	   * Create a new QuickBooks client for a given user.
148	   * Reads encrypted tokens from userIntegrations and decrypts them.
149	   *
150	   * @param userId - The user ID whose QB integration to load
151	   * @throws Error if no QuickBooks integration found for user
152	   */
153	  static async create(userId: string): Promise<QuickBooksClient> {
154	    const [row] = await db
155	      .select()
156	      .from(userIntegrations)
157	      .where(
158	        and(
159	          eq(userIntegrations.userId, userId),
160	          eq(userIntegrations.integrationType, 'quickbooks'),
161	        ),
162	      )
163	      .limit(1);
164	
165	    if (!row?.tokenData) {
166	      throw new Error('No QuickBooks integration found for user');
167	    }
168	
169	    const data = row.tokenData as QBTokenData;
170	
171	    return new QuickBooksClient(
172	      decrypt(data.accessToken),
173	      decrypt(data.refreshToken),
174	      new Date(data.expiresAt),
175	      data.realmId,
176	      userId,
177	      row.id,
178	    );
179	  }
180	
181	  /** Returns the QuickBooks company (realm) ID for this connection. */
182	  getRealmId(): string {
183	    return this.realmId;
184	  }
185	
186	  // ─── Token Management ────────────────────────────────────────────────
187	
188	  /**
189	   * Check if the current access token is expired (or within 60s of expiry).
190	   */
191	  private isTokenExpired(): boolean {
192	    return Date.now() >= this.expiresAt.getTime() - 60_000;
193	  }
194	
195	  /**
196	   * Refresh the access token using the refresh token.
197	   * Persists new encrypted tokens back to the database.
198	   */
199	  private async refreshAccessToken(): Promise<void> {
200	    const clientId = process.env.QB_CLIENT_ID;
201	    const clientSecret = process.env.QB_CLIENT_SECRET;
202	    if (!clientId || !clientSecret) {
203	      throw new Error('QuickBooks client credentials not configured');
204	    }
205	
206	    const basicAuth = Buffer.from(`${clientId}:${clientSecret}`).toString(
207	      'base64',
208	    );
209	
210	    const res = await fetch(INTUIT_TOKEN_URL, {
211	      method: 'POST',
212	      headers: {
213	        'Content-Type': 'application/x-www-form-urlencoded',
214	        Authorization: `Basic ${basicAuth}`,
215	        Accept: 'application/json',
216	      },
217	      body: new URLSearchParams({
218	        grant_type: 'refresh_token',
219	        refresh_token: this.refreshToken,
220	      }),
221	    });
222	
223	    if (!res.ok) {
224	      const errText = await res.text().catch(() => '');
225	      throw new Error(`QB token refresh failed (${res.status}): ${errText}`);
226	    }
227	
228	    const tokens = (await res.json()) as {
229	      access_token: string;
230	      refresh_token: string;
231	      expires_in: number;
232	      x_refresh_token_expires_in: number;
233	    };
234	
235	    this.accessToken = tokens.access_token;
236	    this.refreshToken = tokens.refresh_token;
237	    this.expiresAt = new Date(Date.now() + tokens.expires_in * 1000);
238	
239	    // Persist encrypted tokens back to DB
240	    const tokenData: QBTokenData = {
241	      realmId: this.realmId,
242	      accessToken: encrypt(tokens.access_token),
243	      refreshToken: encrypt(tokens.refresh_token),
244	      expiresAt: this.expiresAt.toISOString(),
245	      refreshExpiresAt: new Date(
246	        Date.now() + tokens.x_refresh_token_expires_in * 1000,
247	      ).toISOString(),
248	      connectedAt: new Date().toISOString(),
249	    };
250	
251	    await db
252	      .update(userIntegrations)
253	      .set({ tokenData, updatedAt: new Date() })
254	      .where(eq(userIntegrations.id, this.integrationId));
255	  }
256	
257	  /**
258	   * Ensure we have a valid access token, refreshing if necessary.
259	   */
260	  private async ensureValidToken(): Promise<void> {
261	    if (this.isTokenExpired()) {
262	      await this.refreshAccessToken();
263	    }
264	  }
265	
266	  // ─── HTTP Layer ──────────────────────────────────────────────────────
267	
268	  /**
269	   * Make an authenticated request to the QuickBooks API.
270	   * On 401, attempts a single token refresh and retries.
271	   */
272	  private async request<T>(
273	    method: string,
274	    path: string,
275	    body?: unknown,
276	  ): Promise<T> {
277	    await this.ensureValidToken();
278	
279	    const url = `${QB_API_BASE}/v3/company/${this.realmId}${path}`;
280	    const headers: Record<string, string> = {
281	      Authorization: `Bearer ${this.accessToken}`,
282	      Accept: 'application/json',
283	      'Content-Type': 'application/json',
284	    };
285	
286	    const doFetch = async (): Promise<Response> => {
287	      const opts: RequestInit = { method, headers };
288	      if (body && (method === 'POST' || method === 'PUT')) {
289	        opts.body = JSON.stringify(body);
290	      }
291	      return fetch(url, opts);
292	    };
293	
294	    let res = await doFetch();
295	
296	    // On 401, refresh token and retry once
297	    if (res.status === 401) {
298	      console.warn('[QuickBooks] 401 received, attempting token refresh...');
299	      await this.refreshAccessToken();
300	      headers.Authorization = `Bearer ${this.accessToken}`;
301	      res = await doFetch();
302	    }
303	
304	    if (!res.ok) {
305	      const errBody = await res.text().catch(() => '');
306	      throw new Error(
307	        `QuickBooks API error (${res.status} ${method} ${path}): ${errBody}`,
308	      );
309	    }
310	
311	    return res.json() as Promise<T>;
312	  }
