1	/**
2	 * QuickBooks Sync Service
3	 *
4	 * Bridges Hilo's Stripe-based billing to QuickBooks Online accounting.
5	 * Syncs invoices and payments so the finance team has a single source
6	 * of truth in QB for AR, revenue recognition, and tax reporting.
7	 *
8	 * Data mapping:
9	 *   Hilo Flight School  →  QB Customer (matched by school name)
10	 *   Hilo Invoice         →  QB Invoice (line items for POE + tax)
11	 *   Stripe Payment       →  QB Payment (closes the QB invoice)
12	 */
13	import { db } from '@/lib/db';
14	import { flightSchools, invoices } from '@/lib/schema';
15	import { qbConnectionRepo } from '@/repositories/quickbooks/qbConnectionRepo';
16	import { eq, sql } from 'drizzle-orm';
17	import { QuickBooksClient } from './quickbooks';
18	
19	// ─── Types ───────────────────────────────────────────────────────────────
20	
21	export interface SyncResult {
22	  success: boolean;
23	  invoiceId: string;
24	  qbInvoiceId?: string;
25	  qbPaymentId?: string;
26	  error?: string;
27	}
28	
29	export interface SyncStatus {
30	  connected: boolean;
31	  totalInvoices: number;
32	  syncedInvoices: number;
33	  unsyncedInvoices: number;
34	  lastSyncTime: string | null;
35	  recentErrors: Array<{ invoiceId: string; error: string; timestamp: string }>;
36	}
37	
38	// ─── In-memory sync tracking ─────────────────────────────────────────────
39	// Since we can't modify the schema, we use an in-memory map for QB IDs
40	// and persist sync metadata in the invoice's invoiceUrl field with a
41	// qb: prefix to distinguish from Stripe URLs. In production, a dedicated
42	// table would be preferred.
43	
44	const QB_PREFIX = 'qb:';
45	
46	interface QBSyncMeta {
47	  qbInvoiceId: string;
48	  qbCustomerId: string;
49	  syncedAt: string;
50	  qbPaymentId?: string;
51	}
52	
53	/**
54	 * Parse QB sync metadata from the invoiceUrl field.
55	 * Returns null if no QB metadata is stored.
56	 */
57	function parseQBMeta(invoiceUrl: string | null): QBSyncMeta | null {
58	  if (!invoiceUrl) return null;
59	
60	  // QB metadata is stored as a JSON suffix after the regular URL
61	  // Format: "original_url||qb:{json}" or just "qb:{json}"
62	  const qbIdx = invoiceUrl.indexOf(QB_PREFIX);
63	  if (qbIdx === -1) return null;
64	
65	  try {
66	    const jsonStr = invoiceUrl.slice(qbIdx + QB_PREFIX.length);
67	    return JSON.parse(jsonStr) as QBSyncMeta;
68	  } catch {
69	    return null;
70	  }
71	}
72	
73	/**
74	 * Store QB sync metadata in the invoiceUrl field, preserving
75	 * any existing URL by appending with a separator.
76	 */
77	function buildQBUrl(existingUrl: string | null, meta: QBSyncMeta): string {
78	  const metaStr = `${QB_PREFIX}${JSON.stringify(meta)}`;
79	  if (existingUrl && !existingUrl.startsWith(QB_PREFIX)) {
80	    return `${existingUrl}||${metaStr}`;
81	  }
82	  return metaStr;
83	}
