85	// ─── Customer cache ──────────────────────────────────────────────────────
86	// Cache school→QB customer ID mappings to avoid repeated QB lookups.
87	
88	const customerCache = new Map<string, string>();
89	
90	// ─── Sync tracking for status endpoint ───────────────────────────────────
91	
92	let lastSyncTime: string | null = null;
93	const recentErrors: Array<{
94	  invoiceId: string;
95	  error: string;
96	  timestamp: string;
97	}> = [];
98	const MAX_RECENT_ERRORS = 20;
99	
100	function recordError(invoiceId: string, error: string): void {
101	  recentErrors.unshift({
102	    invoiceId,
103	    error,
104	    timestamp: new Date().toISOString(),
105	  });
106	  if (recentErrors.length > MAX_RECENT_ERRORS) {
107	    recentErrors.length = MAX_RECENT_ERRORS;
108	  }
109	}
