112	
113	/**
114	 * Find or create a QuickBooks customer for a Hilo flight school.
115	 *
116	 * Searches QB by the school's name. If not found, creates a new
117	 * customer with the school's contact details. Caches the mapping
118	 * to avoid repeated API calls within the same process.
119	 *
120	 * @param client - Authenticated QB client
121	 * @param school - The flight school record from our DB
122	 * @returns The QB customer ID
123	 */
124	async function findOrCreateQBCustomer(
125	  client: QuickBooksClient,
126	  school: {
127	    id: string;
128	    name: string;
129	    email?: string | null;
130	    address?: string | null;
131	    city?: string | null;
132	    state?: string | null;
133	    zip?: string | null;
134	  },
135	): Promise<string> {
136	  // Check cache first
137	  const cached = customerCache.get(school.id);
138	  if (cached) return cached;
139	
140	  // Search QB by display name
141	  const existing = await client.findCustomerByName(school.name);
142	  if (existing.length > 0) {
143	    const customerId = existing[0].Id;
144	    customerCache.set(school.id, customerId);
145	    return customerId;
146	  }
147	
148	  // Create new customer
149	  const result = await client.createCustomer({
150	    DisplayName: school.name,
151	    CompanyName: school.name,
152	    ...(school.email ? { PrimaryEmailAddr: { Address: school.email } } : {}),
153	    ...(school.address
154	      ? {
155	          BillAddr: {
156	            Line1: school.address,
157	            City: school.city ?? undefined,
158	            CountrySubDivisionCode: school.state ?? undefined,
159	            PostalCode: school.zip ?? undefined,
160	          },
161	        }
162	      : {}),
163	  });
164	
165	  const customerId = result.Customer.Id;
166	  customerCache.set(school.id, customerId);
167	  console.log(
168	    `[QB Sync] Created QB customer "${school.name}" (ID: ${customerId})`,
169	  );
170	  return customerId;
171	}
