323	/**
324	 * Sync a payment for an already-synced invoice to QuickBooks.
325	 *
326	 * Creates a QB Payment object that closes the AR for the QB invoice.
327	 * The invoice must be in 'paid' status and already synced to QB.
328	 *
329	 * @param invoiceId - Our internal invoice UUID
330	 * @param qbUserId - The user whose QB integration to use
331	 * @param paymentMethod - 'Credit Card' or 'ACH' (default: 'Credit Card')
332	 * @returns SyncResult with the QB payment ID on success
333	 */
334	export async function syncPaymentToQuickBooks(
335	  invoiceId: string,
336	  qbUserId: string,
337	  paymentMethod = 'Credit Card',
338	): Promise<SyncResult> {
339	  try {
340	    // 1. Fetch invoice (must be paid)
341	    const [invoice] = await db
342	      .select()
343	      .from(invoices)
344	      .where(eq(invoices.id, invoiceId))
345	      .limit(1);
346	
347	    if (!invoice) {
348	      return { success: false, invoiceId, error: 'Invoice not found' };
349	    }
350	
351	    await qbConnectionRepo.findActive(invoice.flightSchoolId);
352	
353	    if (invoice.status !== 'paid') {
354	      return {
355	        success: false,
356	        invoiceId,
357	        error: `Invoice status is "${invoice.status}", expected "paid"`,
358	      };
359	    }
360	
361	    // 2. Find the QB invoice reference
362	    const meta = parseQBMeta(invoice.invoiceUrl);
363	    if (!meta?.qbInvoiceId) {
364	      return {
365	        success: false,
366	        invoiceId,
367	        error: 'Invoice not yet synced to QuickBooks — sync the invoice first',
368	      };
369	    }
370	
371	    // Skip if payment already synced
372	    if (meta.qbPaymentId) {
373	      return {
374	        success: true,
375	        invoiceId,
376	        qbInvoiceId: meta.qbInvoiceId,
377	        qbPaymentId: meta.qbPaymentId,
378	      };
379	    }
380	
381	    // 3. Create QB payment
382	    const client = await QuickBooksClient.create(qbUserId);
383	    const totalAmount = (invoice.amount + (invoice.taxAmount ?? 0)) / 100;
384	
385	    const paymentResult = await client.markInvoicePaid({
386	      CustomerRef: { value: meta.qbCustomerId },
387	      TotalAmt: totalAmount,
388	      Line: [
389	        {
390	          Amount: totalAmount,
391	          LinkedTxn: [
392	            {
393	              TxnId: meta.qbInvoiceId,
394	              TxnType: 'Invoice',
395	            },
396	          ],
397	        },
398	      ],
399	      PaymentMethodRef: { value: '1', name: paymentMethod },
400	      TxnDate: invoice.paidAt
401	        ? new Date(invoice.paidAt).toISOString().split('T')[0]
402	        : new Date().toISOString().split('T')[0],
403	      PrivateNote: `Hilo payment for Invoice ${invoiceId}`,
404	    });
405	
406	    const qbPaymentId = paymentResult.Payment.Id;
407	
408	    // 4. Update stored metadata with payment ID
409	    const updatedMeta: QBSyncMeta = { ...meta, qbPaymentId };
410	    await db
411	      .update(invoices)
412	      .set({ invoiceUrl: buildQBUrl(null, updatedMeta) })
413	      .where(eq(invoices.id, invoiceId));
414	
415	    lastSyncTime = new Date().toISOString();
416	    console.log(
417	      `[QB Sync] Payment for invoice ${invoiceId} synced → QB Payment ${qbPaymentId}`,
418	    );
419	
420	    return {
421	      success: true,
422	      invoiceId,
423	      qbInvoiceId: meta.qbInvoiceId,
424	      qbPaymentId,
425	    };
426	  } catch (err: unknown) {
427	    const msg =
428	      err instanceof Error ? err.message : 'Unknown error during payment sync';
429	    console.error(`[QB Sync] Payment sync failed for ${invoiceId}:`, msg);
430	    recordError(invoiceId, msg);
431	    return { success: false, invoiceId, error: msg };
432	  }
433	}
