435	/**
436	 * Bulk-sync all unsynced invoices from the last N months.
437	 *
438	 * Finds invoices that don't have QB metadata and syncs each one.
439	 * Also syncs payments for any paid invoices. Collects results
440	 * and returns a summary.
441	 *
442	 * @param qbUserId - The user whose QB integration to use
443	 * @param months - How many months back to look (default: 3)
444	 * @returns Array of SyncResults for each invoice processed
445	 */
446	export async function bulkSyncInvoices(
447	  qbUserId: string,
448	  months = 3,
449	): Promise<{
450	  total: number;
451	  synced: number;
452	  failed: number;
453	  results: SyncResult[];
454	}> {
455	  const cutoff = new Date();
456	  cutoff.setMonth(cutoff.getMonth() - months);
457	
458	  // Find invoices created after the cutoff
459	  const allInvoices = await db
460	    .select()
461	    .from(invoices)
462	    .where(sql`${invoices.createdAt} >= ${cutoff}`);
463	
464	  // Filter to unsynced (no QB metadata in invoiceUrl)
465	  const unsynced = allInvoices.filter((inv) => !parseQBMeta(inv.invoiceUrl));
466	
467	  const results: SyncResult[] = [];
468	  let synced = 0;
469	  let failed = 0;
470	
471	  for (const inv of unsynced) {
472	    // Sync invoice
473	    const invoiceResult = await syncInvoiceToQuickBooks(inv.id, qbUserId);
474	    if (invoiceResult.success) {
475	      synced++;
476	
477	      // If paid, also sync the payment
478	      if (inv.status === 'paid') {
479	        const paymentResult = await syncPaymentToQuickBooks(inv.id, qbUserId);
480	        if (!paymentResult.success) {
481	          console.warn(
482	            `[QB Sync] Bulk: payment sync failed for ${inv.id}: ${paymentResult.error}`,
483	          );
484	        }
485	        results.push(paymentResult);
486	      } else {
487	        results.push(invoiceResult);
488	      }
489	    } else {
490	      failed++;
491	      results.push(invoiceResult);
492	    }
493	  }
494	
495	  lastSyncTime = new Date().toISOString();
496	  return { total: unsynced.length, synced, failed, results };
497	}
498	
499	/**
500	 * Get the current sync status — how many invoices are synced vs not,
501	 * last sync time, and any recent errors.
502	 *
503	 * @returns SyncStatus object for the status dashboard
504	 */
505	export async function getSyncStatus(): Promise<SyncStatus> {
506	  const activeConnections = await qbConnectionRepo.findAllActive();
507	  const connected = activeConnections.length > 0;
508	
509	  // Count total invoices
510	  const allInvoices = await db.select().from(invoices);
511	  const total = allInvoices.length;
512	  const syncedCount = allInvoices.filter(
513	    (inv) => parseQBMeta(inv.invoiceUrl) !== null,
514	  ).length;
515	
516	  return {
517	    connected,
518	    totalInvoices: total,
519	    syncedInvoices: syncedCount,
520	    unsyncedInvoices: total - syncedCount,
521	    lastSyncTime,
522	    recentErrors: [...recentErrors],
523	  };
524	}
