1	/**
2	 * QuickBooks Webhook Handler
3	 *
4	 * Provides hook functions designed to be called from the Stripe webhook
5	 * handler. These are safe to call — they catch all errors internally
6	 * so QB sync failures never break payment processing.
7	 *
8	 * Usage from stripe-webhook/route.ts:
9	 *   import { onInvoicePaid, onInvoiceCreated } from '@/lib/quickbooks-webhook-handler';
10	 *
11	 *   // In invoice.paid handler:
12	 *   await onInvoicePaid(stripeInvoiceId);
13	 *
14	 *   // In invoice.created handler:
15	 *   await onInvoiceCreated(stripeInvoiceId);
16	 */
17	import { db } from '@/lib/db';
18	import { invoices, userIntegrations } from '@/lib/schema';
19	import { eq } from 'drizzle-orm';
20	import {
21	  syncInvoiceToQuickBooks,
22	  syncPaymentToQuickBooks,
23	} from './quickbooks-sync';
24	
25	function legacyUserScopedQuickBooksEnabled(): boolean {
26	  return process.env.ENABLE_LEGACY_USER_SCOPED_QB_SYNC === 'true';
27	}
28	
29	/**
30	 * Resolve the QB user ID — the first user with an active QB integration.
31	 * In a multi-user system this would be scoped, but for Hilo the super
32	 * admin connects QB once and all syncs flow through that connection.
33	 */
34	async function getQBUserId(): Promise<string | null> {
35	  try {
36	    const [row] = await db
37	      .select({ userId: userIntegrations.userId })
38	      .from(userIntegrations)
39	      .where(eq(userIntegrations.integrationType, 'quickbooks'))
40	      .limit(1);
41	
42	    return row?.userId ?? null;
43	  } catch (err) {
44	    console.error('[QB Webhook] Failed to resolve QB user:', err);
45	    return null;
46	  }
47	}
48	
49	/**
50	 * Find our internal invoice ID by Stripe invoice ID.
51	 */
52	async function findInvoiceByStripeId(
53	  stripeInvoiceId: string,
54	): Promise<string | null> {
55	  try {
56	    const [row] = await db
57	      .select({ id: invoices.id })
58	      .from(invoices)
59	      .where(eq(invoices.stripeInvoiceId, stripeInvoiceId))
60	      .limit(1);
61	
62	    return row?.id ?? null;
63	  } catch (err) {
64	    console.error(
65	      `[QB Webhook] Failed to look up invoice for Stripe ID ${stripeInvoiceId}:`,
66	      err,
67	    );
68	    return null;
69	  }
70	}
71	
72	/**
73	 * Called when a Stripe invoice is paid.
74	 *
75	 * Syncs the invoice to QuickBooks (if not already synced) and then
76	 * records the payment in QuickBooks to close the AR.
77	 *
78	 * Safe to call from webhook handlers — all errors are caught and logged.
79	 * QB sync failure does NOT affect payment processing.
80	 *
81	 * @param stripeInvoiceId - The Stripe invoice ID (e.g. "in_xxx")
82	 */
83	export async function onInvoicePaid(stripeInvoiceId: string): Promise<void> {
84	  try {
85	    if (!legacyUserScopedQuickBooksEnabled()) {
86	      console.warn(
87	        '[QB Webhook] Legacy user-scoped QuickBooks sync is disabled; owner-scoped Hilo QuickBooks posting must handle this event',
88	      );
89	      return;
90	    }
91	
92	    const qbUserId = await getQBUserId();
93	    if (!qbUserId) {
94	      console.log(
95	        '[QB Webhook] No QuickBooks integration found — skipping sync',
96	      );
97	      return;
98	    }
99	
100	    const invoiceId = await findInvoiceByStripeId(stripeInvoiceId);
101	    if (!invoiceId) {
102	      console.warn(
103	        `[QB Webhook] No matching invoice found for Stripe ID ${stripeInvoiceId}`,
104	      );
105	      return;
106	    }
107	
108	    // Sync invoice first (idempotent — no-op if already synced)
109	    const invoiceResult = await syncInvoiceToQuickBooks(invoiceId, qbUserId);
110	    if (!invoiceResult.success) {
111	      console.error(
112	        `[QB Webhook] Invoice sync failed for ${invoiceId}: ${invoiceResult.error}`,
113	      );
114	      return;
115	    }
116	
117	    // Then sync the payment
118	    const paymentResult = await syncPaymentToQuickBooks(invoiceId, qbUserId);
119	    if (!paymentResult.success) {
120	      console.error(
121	        `[QB Webhook] Payment sync failed for ${invoiceId}: ${paymentResult.error}`,
122	      );
123	      return;
124	    }
125	
126	    console.log(
127	      `[QB Webhook] Invoice ${stripeInvoiceId} fully synced to QB (Invoice: ${paymentResult.qbInvoiceId}, Payment: ${paymentResult.qbPaymentId})`,
128	    );
129	  } catch (err) {
130	    // Catch-all: QB sync failures must NEVER propagate to the webhook handler
131	    console.error(
132	      `[QB Webhook] Unexpected error syncing paid invoice ${stripeInvoiceId}:`,
133	      err,
134	    );
135	  }
136	}
137	
138	/**
139	 * Called when a Stripe invoice is created (but not yet paid).
140	 *
141	 * Syncs the invoice to QuickBooks so it appears as open AR.
142	 *
143	 * Safe to call from webhook handlers — all errors are caught and logged.
144	 *
145	 * @param stripeInvoiceId - The Stripe invoice ID (e.g. "in_xxx")
146	 */
147	export async function onInvoiceCreated(stripeInvoiceId: string): Promise<void> {
148	  try {
149	    if (!legacyUserScopedQuickBooksEnabled()) {
150	      console.warn(
151	        '[QB Webhook] Legacy user-scoped QuickBooks sync is disabled; owner-scoped Hilo QuickBooks posting must handle this event',
152	      );
153	      return;
154	    }
155	
156	    const qbUserId = await getQBUserId();
157	    if (!qbUserId) {
158	      console.log(
159	        '[QB Webhook] No QuickBooks integration found — skipping sync',
160	      );
161	      return;
162	    }
163	
164	    const invoiceId = await findInvoiceByStripeId(stripeInvoiceId);
165	    if (!invoiceId) {
166	      console.warn(
167	        `[QB Webhook] No matching invoice found for Stripe ID ${stripeInvoiceId}`,
168	      );
169	      return;
170	    }
171	
172	    const result = await syncInvoiceToQuickBooks(invoiceId, qbUserId);
173	    if (!result.success) {
174	      console.error(
175	        `[QB Webhook] Invoice sync failed for ${invoiceId}: ${result.error}`,
176	      );
177	      return;
178	    }
179	
180	    console.log(
181	      `[QB Webhook] Invoice ${stripeInvoiceId} synced to QB Invoice ${result.qbInvoiceId}`,
182	    );
183	  } catch (err) {
184	    // Catch-all: QB sync failures must NEVER propagate to the webhook handler
185	    console.error(
186	      `[QB Webhook] Unexpected error syncing created invoice ${stripeInvoiceId}:`,
187	      err,
188	    );
189	  }
190	}
