7	// ─────────────────────────────────────────────────────────────────────────────
8	// Transaction type
9	// ─────────────────────────────────────────────────────────────────────────────
10	
11	type DbTx = Parameters<Parameters<typeof withTransaction>[0]>[0];
12	
13	export function redactQbSyncLogMessage(
14	  message: string | undefined,
15	): string | undefined {
16	  if (!message) return message;
17	  return message
18	    .replace(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/gi, '[redacted_email]')
19	    .replace(/\b(?:\d[ -]?){13,19}\b/g, '[redacted_card]')
20	    .replace(
21	      /\b(?:sk|rk|pk|pi|pm|cus|acct|in|ch|seti)_[A-Za-z0-9_]+/g,
22	      (match) => {
23	        const [prefix] = match.split('_');
24	        return `${prefix}_[redacted]`;
25	      },
26	    );
27	}
28	
29	// ─────────────────────────────────────────────────────────────────────────────
30	// Writes
31	// ─────────────────────────────────────────────────────────────────────────────
32	
33	/**
34	 * Insert a sync log entry.
35	 *
36	 * Fire-and-forget: wraps the DB write in try/catch and never throws.
37	 * Logging must never interrupt the primary sync path.
38	 * Errors are console.error'd only — not re-thrown, not surfaced to caller.
39	 */
40	export async function insert(
41	  data: InsertQbSyncLogInput,
42	  tx?: DbTx,
43	): Promise<void> {
44	  try {
45	    const client = tx ?? db;
46	    await client.insert(qbSyncLog).values({
47	      flightSchoolId: data.flightSchoolId,
48	      operation: data.operation,
49	      entityType: data.entityType,
50	      atosEntityId: data.atosEntityId,
51	      qbEntityId: data.qbEntityId,
52	      status: data.status,
53	      qbErrorCode: data.qbErrorCode,
54	      qbErrorMessage: redactQbSyncLogMessage(data.qbErrorMessage),
55	      httpStatus: data.httpStatus,
56	      attemptNumber: data.attemptNumber ?? '1',
57	      durationMs: data.durationMs,
58	    });
59	  } catch (err) {
60	    const msg =
61	      err instanceof Error
62	        ? err.message
63	        : typeof err === 'object' && err !== null
64	          ? JSON.stringify(err)
65	          : String(err);
66	    console.error('[qbSyncLogRepo.insert] Failed to write sync log:', msg);
67	    // Never re-throw — sync log is non-critical
68	  }
69	}
70	
71	// ─────────────────────────────────────────────────────────────────────────────
72	// Queries
73	// ─────────────────────────────────────────────────────────────────────────────
