75	/**
76	 * Fetch sync log entries for a flight school.
77	 * Always scoped to flightSchoolId — never returns rows from other schools.
78	 * Used by the admin UI sync status panel.
79	 */
80	export async function findBySchool(
81	  flightSchoolId: string,
82	  filters: {
83	    status?: string;
84	    entityType?: string;
85	    limit?: number;
86	  } = {},
87	): Promise<QbSyncLog[]> {
88	  const conditions = [eq(qbSyncLog.flightSchoolId, flightSchoolId)];
89	
90	  if (filters.status !== undefined) {
91	    conditions.push(eq(qbSyncLog.status, filters.status));
92	  }
93	
94	  if (filters.entityType !== undefined) {
95	    conditions.push(eq(qbSyncLog.entityType, filters.entityType));
96	  }
97	
98	  return db
99	    .select()
100	    .from(qbSyncLog)
101	    .where(and(...conditions))
102	    .orderBy(desc(qbSyncLog.createdAt))
103	    .limit(filters.limit ?? 100);
104	}
