8	export interface QBRefMapping {
9	  id: string;
10	  name: string;
11	}
12	
13	export interface QBInvoiceMappingConfig {
14	  itemMappings: Record<string, QBRefMapping>;
15	  classMappings: Record<string, QBRefMapping>;
16	}
17	
18	const LEGACY_TO_BILLING_REVENUE_CATEGORY: Record<string, string> = {
19	  aircraft_rental: 'airplane',
20	  simulator_rental: 'sim',
21	  flight_instruction: 'instruction',
22	  ground_instruction: 'instruction',
23	  checkride_fee: 'checkride',
24	  fees: 'other',
25	  processing_fee: 'other',
26	  product_sales: 'other',
27	  course_revenue: 'other',
28	  subscription_revenue: 'other',
29	};
30	
31	const BILLING_TO_LEGACY_REVENUE_CATEGORIES: Record<string, string[]> = {
32	  airplane: ['aircraft_rental'],
33	  sim: ['simulator_rental'],
34	  instruction: ['flight_instruction', 'ground_instruction'],
35	  checkride: ['checkride_fee'],
36	  knowledge: [],
37	  other: [
38	    'fees',
39	    'processing_fee',
40	    'product_sales',
41	    'course_revenue',
42	    'subscription_revenue',
43	  ],
44	};
45	
46	function addMapping(
47	  target: Record<string, QBRefMapping>,
48	  key: string,
49	  id: string | null | undefined,
50	  name?: string | null,
51	) {
52	  const normalizedKey = key.trim();
53	  if (!normalizedKey || !id) return;
54	  target[normalizedKey] = { id, name: name || id };
55	}
56	
57	function mappingKeyAliases(internalType: string, internalId: string) {
58	  switch (internalType) {
59	    case 'aircraft':
60	      return [`aircraft:${internalId}`];
61	    case 'aircraft_tail':
62	      return [`aircraft_tail:${internalId.toUpperCase()}`];
63	    case 'simulator':
64	      return [`simulator:${internalId}`];
65	    case 'instructor':
66	      return [`instructor:${internalId}`];
67	    case 'instructor_item':
68	      return [`instructor:${internalId}`];
69	    case 'product':
70	      return [`product:${internalId}`];
71	    case 'revenue_category': {
72	      const aliases = new Set([internalId, `category:${internalId}`]);
73	      const canonical = LEGACY_TO_BILLING_REVENUE_CATEGORY[internalId];
74	      if (canonical) {
75	        aliases.add(canonical);
76	        aliases.add(`category:${canonical}`);
77	      }
78	      for (const legacyKey of BILLING_TO_LEGACY_REVENUE_CATEGORIES[
79	        internalId
80	      ] ?? []) {
81	        aliases.add(legacyKey);
82	        aliases.add(`category:${legacyKey}`);
83	      }
84	      return [...aliases];
85	    }
86	    default:
87	      return [`${internalType}:${internalId}`];
88	  }
89	}
90	
91	function isUsableQuickBooksStatus(status: string | null | undefined) {
92	  return status === 'active' || status === 'refresh_expiring_soon';
93	}
94	
95	async function resolveProviderAccountId(flightSchoolId: string) {
96	  const [providerConnection] = await db
97	    .select({
98	      providerAccountId: schema.accountingProviderConnections.providerAccountId,
99	    })
100	    .from(schema.accountingProviderConnections)
101	    .where(
102	      and(
103	        eq(schema.accountingProviderConnections.ownerType, 'FLIGHT_SCHOOL'),
104	        eq(schema.accountingProviderConnections.ownerId, flightSchoolId),
105	        eq(schema.accountingProviderConnections.provider, 'QUICKBOOKS'),
106	        eq(schema.accountingProviderConnections.status, 'active'),
107	      ),
108	    )
109	    .orderBy(desc(schema.accountingProviderConnections.updatedAt))
110	    .limit(1);
111	
112	  if (providerConnection?.providerAccountId) {
113	    return providerConnection.providerAccountId;
114	  }
115	
116	  const qbConnection = await qbConnectionRepo.findBySchool(flightSchoolId);
117	  return isUsableQuickBooksStatus(qbConnection?.status)
118	    ? (qbConnection?.realmId ?? null)
119	    : null;
120	}
121	
122	export async function getInvoiceMappings(
123	  flightSchoolId: string,
124	): Promise<QBInvoiceMappingConfig> {
125	  const providerAccountId = await resolveProviderAccountId(flightSchoolId);
126	  if (!providerAccountId) return { itemMappings: {}, classMappings: {} };
127	
128	  const rows = await db
129	    .select()
130	    .from(schema.integrationObjectMappings)
131	    .where(
132	      and(
133	        eq(schema.integrationObjectMappings.ownerType, 'FLIGHT_SCHOOL'),
134	        eq(schema.integrationObjectMappings.ownerId, flightSchoolId),
135	        eq(schema.integrationObjectMappings.provider, 'QUICKBOOKS'),
136	        eq(
137	          schema.integrationObjectMappings.providerAccountId,
138	          providerAccountId,
139	        ),
140	      ),
141	    );
142	
143	  const itemMappings: Record<string, QBRefMapping> = {};
144	  const classMappings: Record<string, QBRefMapping> = {};
145	
146	  for (const row of rows) {
147	    const target =
148	      row.externalObjectType === 'class'
149	        ? classMappings
150	        : row.externalObjectType === 'item'
151	          ? itemMappings
152	          : null;
153	    if (!target) continue;
154	
155	    for (const key of mappingKeyAliases(
156	      row.internalObjectType,
157	      row.internalObjectId,
158	    )) {
159	      addMapping(target, key, row.externalObjectId);
160	    }
161	  }
162	
163	  return { itemMappings, classMappings };
164	}
165	
166	export async function getItemMappings(
167	  flightSchoolId: string,
168	): Promise<Record<string, QBRefMapping>> {
169	  const config = await getInvoiceMappings(flightSchoolId);
170	  return config.itemMappings;
171	}
172	
173	export const qbConfigRepo = {
174	  getInvoiceMappings,
175	  getItemMappings,
176	} as const;
